/** Conversions between the application models and the "customers" table: what the service takes and returns. */
import type { Customer as CustomerModel, CustomerResponse } from '../application-models.js'
import { Customer } from '../entities/customer.js'

/** A Customer as the customers table takes it. */
export function customerModelToCustomer(model: CustomerModel): Customer {
  return Object.assign(new Customer(), {
    email: model.email,
    // TODO: fullName: the matching waits for review (fullName)
    fullName: undefined as never,
  })
}

/** A row of the customers table as a Customer. */
export function customerToCustomerModel(row: Customer): CustomerModel {
  return {
    id: row.id,
    email: row.email,
    // TODO: fullName: the matching waits for review (fullName)
    fullName: undefined as never,
  }
}

/** A row of the customers table as a CustomerResponse. */
export function customerToCustomerResponse(row: Customer): CustomerResponse {
  return {
    id: row.id,
    email: row.email,
    createdAt: row.createdAt,
  }
}

