/** Conversions between the application models and the "orders" table: what the service takes and returns. */
import type { OrderRequest, OrderResponse } from '../application-models.js'
import { Order } from '../entities/order.js'
import { NotFoundError } from '../errors.js'
import type { UnitOfWork } from '../unit-of-work.js'

/** An OrderRequest as the orders table takes it. */
export async function orderRequestToOrder(model: OrderRequest, uow: UnitOfWork): Promise<Order> {
  const customer = await uow.customers.findByEmail(model.customerEmail)
  if (!customer) throw new NotFoundError('Customer', model.customerEmail)
  return Object.assign(new Order(), {
    customerId: customer.id,
    quantity: model.quantity,
    unitPrice: model.unitPrice,
  })
}

/** A row of the orders table as an OrderResponse. */
export function orderToOrderResponse(row: Order): OrderResponse {
  return {
    id: row.id,
    // TODO: status: the matching waits for review (status)
    status: undefined as never,
    total: row.total,
    // TODO: shippedAt: the matching waits for review (shippedAt)
    shippedAt: undefined as never,
  }
}

