/** The tables of the database, as Sequelize models. They reflect the database: never sync them with it. */
import { DataTypes, literal, type Model, type ModelStatic, type Sequelize } from 'sequelize'

/** The model of every table */
export interface Models {
  customers: ModelStatic<Model>
  products: ModelStatic<Model>
  orders: ModelStatic<Model>
}

/** Defines the model of every table on `sequelize`. */
export function defineModels(sequelize: Sequelize): Models {
  /** The "customers" table. */
  const customers = sequelize.define(
    'customers',
    {
      id: { type: DataTypes.INTEGER, primaryKey: true, autoIncrement: true, allowNull: false },
      email: { type: DataTypes.STRING(120), allowNull: false },
      fullName: { type: DataTypes.STRING(80), allowNull: false, field: 'full_name' },
      createdAt: { type: DataTypes.DATE, allowNull: false, defaultValue: literal('CURRENT_TIMESTAMP'), field: 'created_at' },
    },
    {
      tableName: 'customers',
      timestamps: false,
      indexes: [
        { unique: true, fields: ['email'] },
      ],
    },
  )

  /** The "products" table. */
  const products = sequelize.define(
    'products',
    {
      id: { type: DataTypes.INTEGER, primaryKey: true, autoIncrement: true, allowNull: false },
      name: { type: DataTypes.STRING(80), allowNull: false },
      price: { type: DataTypes.DECIMAL(10, 2), allowNull: false },
    },
    { tableName: 'products', timestamps: false },
  )

  /** The "orders" table. */
  // CHECK (status IN ('open', 'shipped', 'cancelled')): Sequelize does not keep CHECK constraints; the services check them
  const orders = sequelize.define(
    'orders',
    {
      id: { type: DataTypes.INTEGER, primaryKey: true, autoIncrement: true, allowNull: false },
      customerId: { type: DataTypes.INTEGER, allowNull: false, field: 'customer_id', references: { model: 'customers', key: 'id' }, onDelete: 'NO ACTION', onUpdate: 'NO ACTION' },
      status: { type: DataTypes.STRING(20), allowNull: false, defaultValue: 'open' },
      quantity: { type: DataTypes.INTEGER, allowNull: false },
      unitPrice: { type: DataTypes.DECIMAL(10, 2), allowNull: false, field: 'unit_price' },
      // TODO: total is computed by the database (quantity * unit_price); Sequelize cannot say so, and the repositories never write it
      total: { type: DataTypes.DECIMAL(12, 2), allowNull: true },
      shippedAt: { type: DataTypes.DATE, allowNull: true, field: 'shipped_at' },
    },
    { tableName: 'orders', timestamps: false },
  )
  return { customers, products, orders }
}

