/** Repository of the "customers" table: reads and writes rows, and decides nothing. */
import { DatabaseError, ValidationError, type Model, type Transaction } from 'sequelize'
import type { Db } from '../database.js'
import { Customer } from '../entities/customer.js'
import { ConflictError } from '../errors.js'
import type { Page } from '../paging.js'

/** Where customers rows are kept. Services depend only on this interface. */
export interface CustomerRepository {
  findById(id: number): Promise<Customer | null>
  list(offset?: number, limit?: number): Promise<Page<Customer>>
  findByEmail(email: string): Promise<Customer | null>
  insert(entity: Customer): Promise<Customer>
  update(entity: Customer): Promise<Customer>
  delete(entity: Customer): Promise<void>
}

/** The Customer of an instance Sequelize read. */
function toEntity(instance: Model): Customer {
  const row = instance.get({ plain: true }) as Record<string, unknown>
  return Object.assign(new Customer(), {
    id: row.id as number,
    email: row.email as string,
    fullName: row.fullName as string,
    createdAt: row.createdAt as Date,
  })
}

/** The values of a new row; those left undefined take the database's default. */
function insertValues(entity: Customer): Record<string, unknown> {
  const values: Record<string, unknown> = {
    id: entity.id,
    email: entity.email,
    fullName: entity.fullName,
    createdAt: entity.createdAt,
  }
  return Object.fromEntries(Object.entries(values).filter(([, value]) => value !== undefined))
}

/** The values a change writes: not the key, nor what the database fills. */
function updateValues(entity: Customer): Record<string, unknown> {
  return {
    email: entity.email,
    fullName: entity.fullName,
  }
}

/** Keeps customers rows in the database, through Sequelize. It never commits: queries run in the transaction it was given. */
export class SqlCustomerRepository implements CustomerRepository {
  constructor(
    private readonly db: Db,
    private readonly transaction: Transaction | null = null,
  ) {}

  /** The row with this primary key, or null. */
  async findById(id: number): Promise<Customer | null> {
    const row = await this.db.models.customers.findOne({ where: { id }, transaction: this.transaction })
    return row === null ? null : toEntity(row)
  }

  /** At most `limit` rows from `offset`, by primary key, and how many there are. */
  async list(offset: number = 0, limit: number = 50): Promise<Page<Customer>> {
    const { rows, count } = await this.db.models.customers.findAndCountAll({ order: [['id', 'ASC']], offset, limit, transaction: this.transaction })
    return { items: rows.map(toEntity), total: count, offset, limit }
  }

  /** The row with this email, or null. */
  async findByEmail(email: string): Promise<Customer | null> {
    const row = await this.db.models.customers.findOne({ where: { email }, transaction: this.transaction })
    return row === null ? null : toEntity(row)
  }

  /** Stores a new row; the values the database fills are read back. */
  async insert(entity: Customer): Promise<Customer> {
    try {
      const row = await this.db.models.customers.create(insertValues(entity), { transaction: this.transaction })
      await row.reload({ transaction: this.transaction })
      return Object.assign(entity, toEntity(row))
    } catch (error) {
      if (error instanceof DatabaseError || error instanceof ValidationError)
        throw new ConflictError('Customer', `the database refused the change: ${error.message}`)
      throw error
    }
  }

  /** Stores the changes made to a row read from this repository. */
  async update(entity: Customer): Promise<Customer> {
    try {
      await this.db.models.customers.update(updateValues(entity), { where: { id: entity.id }, transaction: this.transaction })
    } catch (error) {
      if (error instanceof DatabaseError || error instanceof ValidationError)
        throw new ConflictError('Customer', `the database refused the change: ${error.message}`)
      throw error
    }
    return entity
  }

  /** Removes a row read from this repository. */
  async delete(entity: Customer): Promise<void> {
    try {
      await this.db.models.customers.destroy({ where: { id: entity.id }, transaction: this.transaction })
    } catch (error) {
      if (error instanceof DatabaseError || error instanceof ValidationError)
        throw new ConflictError('Customer', `the database refused the change: ${error.message}`)
      throw error
    }
  }
}

