    name: entity.name,
    price: entity.price,
  }
  return Object.fromEntries(Object.entries(values).filter(([, value]) => value !== undefined))
}

/** The values a change writes: not the key, nor what the database fills. */
function updateValues(entity: Product): Record<string, unknown> {
  return {
    name: entity.name,
    price: entity.price,
  }
}

/** Keeps products rows in the database, through Sequelize. It never commits: queries run in the transaction it was given. */
export class SqlProductRepository implements ProductRepository {
  constructor(
    private readonly db: Db,
    private readonly transaction: Transaction | null = null,
  ) {}

  /** The row with this primary key, or null. */
  async findById(id: number): Promise<Product | null> {
    const row = await this.db.models.products.findOne({ where: { id }, transaction: this.transaction })
    return row === null ? null : toEntity(row)
  }

  /** At most `limit` rows from `offset`, by primary key, and how many there are. */
  async list(offset: number = 0, limit: number = 50): Promise<Page<Product>> {
    const { rows, count } = await this.db.models.products.findAndCountAll({ order: [['id', 'ASC']], offset, limit, transaction: this.transaction })
    return { items: rows.map(toEntity), total: count, offset, limit }
  }

  /** Stores a new row; the values the database fills are read back. */
  async insert(entity: Product): Promise<Product> {
    try {
      const row = await this.db.models.products.create(insertValues(entity), { transaction: this.transaction })
      await row.reload({ transaction: this.transaction })
      return Object.assign(entity, toEntity(row))
    } catch (error) {
      if (error instanceof DatabaseError || error instanceof ValidationError)
        throw new ConflictError('Product', `the database refused the change: ${error.message}`)
      throw error
    }
  }

  /** Stores the changes made to a row read from this repository. */
  async update(entity: Product): Promise<Product> {
    try {
      await this.db.models.products.update(updateValues(entity), { where: { id: entity.id }, transaction: this.transaction })
    } catch (error) {
      if (error instanceof DatabaseError || error instanceof ValidationError)
        throw new ConflictError('Product', `the database refused the change: ${error.message}`)
      throw error
    }
    return entity
  }

  /** Removes a row read from this repository. */
  async delete(entity: Product): Promise<void> {
    try {
      await this.db.models.products.destroy({ where: { id: entity.id }, transaction: this.transaction })
    } catch (error) {
      if (error instanceof DatabaseError || error instanceof ValidationError)
        throw new ConflictError('Product', `the database refused the change: ${error.message}`)
      throw error
    }
  }
}

