/** The repositories of every table, and the transaction of each service operation. Each service operation runs in `transaction()`: committed when it ends, rolled back when it fails. */
import type { Transaction } from 'sequelize'
import type { Db } from './database.js'
import { SqlCustomerRepository, type CustomerRepository } from './repositories/customer.js'
import { SqlOrderRepository, type OrderRepository } from './repositories/order.js'
import { SqlProductRepository, type ProductRepository } from './repositories/product.js'

/** What services depend on: a repository per table and a transaction. */
export interface UnitOfWork {
  readonly customers: CustomerRepository
  readonly products: ProductRepository
  readonly orders: OrderRepository
  /** Runs `work` with the repositories of the transaction; commits when it ends, rolls back when it throws. */
  transaction<T>(work: (uow: UnitOfWork) => Promise<T>): Promise<T>
}

/** The repositories over one database and, when there is one, the transaction every query runs in. */
export class SqlUnitOfWork implements UnitOfWork {
  readonly customers: CustomerRepository
  readonly products: ProductRepository
  readonly orders: OrderRepository

  constructor(
    readonly db: Db,
    readonly current: Transaction | null = null,
  ) {
    this.customers = new SqlCustomerRepository(db, current)
    this.products = new SqlProductRepository(db, current)
    this.orders = new SqlOrderRepository(db, current)
  }

  /** Runs `work` in a transaction of its own, or in the one already open. */
  transaction<T>(work: (uow: UnitOfWork) => Promise<T>): Promise<T> {
    if (this.current) return work(this)
    return this.db.sequelize.transaction((transaction) => work(new SqlUnitOfWork(this.db, transaction)))
  }
}

