/** A valid Order that is not stored yet; `n` makes its unique values differ, `values` replace any of them. */
export function newOrder(n = 1, values: Partial<Order> = {}): Order {
  return Object.assign(new Order(), { status: 'open', quantity: n, unitPrice: `${n % 10000}.50`, shippedAt: new Date(Date.UTC(2026, 0, (n % 28) + 1, 12, 0, 0)) }, values)
}

/** A stored Order, with the rows it points to. */
export async function addOrder(uow: UnitOfWork, n = 1): Promise<Order> {
  const parent0 = await addCustomer(uow, n)
  return uow.orders.insert(newOrder(n, { customerId: parent0.id }))
}

